// Builds the single-file companion (Node SEA) for one target:
//   pnpm package --target linux-x64|linux-arm64|windows-x64 [--version 1.2.3] [--out output/dist]
// The embedded runtime is the pinned Node release in runtime.json, downloaded from nodejs.org and checked
// against the pinned SHA-256, so the result does not depend on the Node running this script. Cross-building
// (e.g. windows-x64 on Linux) works because the blob is generated by the pinned runtime for the host.
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { chmodSync, copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";
import { build } from "esbuild";
import { inject } from "postject";
import { osName, releaseAssetName } from "../src/update.js";

export const TARGETS = ["linux-x64", "linux-arm64", "windows-x64"] as const;
export type Target = typeof TARGETS[number];
type Runtime = { version: string; files: Record<Target, { path: string; sha256: string }> };

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const runtime = JSON.parse(readFileSync(join(root, "scripts", "runtime.json"), "utf8")) as Runtime;
const SEA_FUSE = "NODE_SEA_FUSE_fce680ab2cc467b6e072b8b5df1996b2";
export const NOTICES_FILE = "THIRD_PARTY_NOTICES.txt";
export const LICENSE_FILE = "LICENSE";

const platformOf = (target: Target): NodeJS.Platform => target.startsWith("windows") ? "win32" : "linux";
export const assetName = (target: Target, version: string) => releaseAssetName(version, platformOf(target), target.split("-")[1]!);
const hostTarget = (): Target => {
  const host = `${osName(process.platform)}-${process.arch}`;
  if (!(TARGETS as readonly string[]).includes(host)) throw new Error(`Unsupported build host ${host}`);
  return host as Target;
};
const sha256 = (data: Buffer) => createHash("sha256").update(data).digest("hex");

async function nodeBinary(target: Target, cache: string) {
  const file = runtime.files[target];
  const binary = join(cache, `node-v${runtime.version}-${target}`, target.startsWith("windows") ? "node.exe" : "node");
  if (existsSync(binary)) return binary;
  const response = await fetch(`https://nodejs.org/dist/v${runtime.version}/${file.path}`, { signal: AbortSignal.timeout(300_000) });
  if (!response.ok) throw new Error(`Node download failed (${response.status})`);
  const data = Buffer.from(await response.arrayBuffer());
  if (sha256(data) !== file.sha256) throw new Error(`Checksum mismatch for ${file.path}`);
  mkdirSync(dirname(binary), { recursive: true });
  if (file.path.endsWith(".exe")) { writeFileSync(`${binary}.tmp`, data); renameSync(`${binary}.tmp`, binary); return binary; }
  const archive = join(cache, file.path); writeFileSync(archive, data);
  const member = `${file.path.replace(/\.tar\.xz$/, "")}/bin/node`;
  run("tar", ["-xJf", archive, "-C", dirname(binary), "--strip-components=2", member]);
  rmSync(archive); chmodSync(binary, 0o755);
  return binary;
}

/**
 * Licence texts for everything inside the binary: the embedded Node runtime (scripts/node-LICENSE, taken from
 * the tag of runtime.json's version; update both together) and every npm package esbuild bundled. `inputs` are the
 * bundle's input paths relative to the repository root (esbuild metafile).
 */
export function thirdPartyNotices(inputs: string[]) {
  const packages = new Set<string>();
  for (const input of inputs) {
    const match = /^(.*node_modules\/(?:@[^/]+\/)?[^/]+)\//.exec(input.replaceAll("\\", "/"));
    if (match) packages.add(resolve(root, match[1]!));
  }
  const sections = [`Node.js ${runtime.version} (embedded runtime)\n\n${readFileSync(join(root, "scripts", "node-LICENSE"), "utf8").trim()}`];
  for (const dir of [...packages].sort()) {
    const pkg = JSON.parse(readFileSync(join(dir, "package.json"), "utf8")) as { name: string; version: string; license?: string };
    const file = readdirSync(dir).find(name => /^(licen[cs]e|copying)(\.|$)/i.test(name));
    if (!file) throw new Error(`${pkg.name} ships no licence file; add its notice before bundling it`);
    sections.push(`${pkg.name} ${pkg.version} (${pkg.license ?? "see below"})\n\n${readFileSync(join(dir, file), "utf8").trim()}`);
  }
  return `Meterkat companion: third-party notices\n\n${sections.join(`\n\n${"=".repeat(72)}\n\n`)}\n`;
}

function run(command: string, args: string[]) {
  const result = spawnSync(command, args, { stdio: "inherit" });
  if (result.status !== 0) throw new Error(`${command} failed (${result.status ?? result.error?.message})`);
}

// Injecting the blob invalidates node.exe's Authenticode signature. An unsigned build is expected (no code signing yet);
// a corrupt signature is not, so the certificate table (always at the end of the file) is removed first.
export function stripPeSignature(data: Buffer) {
  const pe = data.readUInt32LE(0x3c);
  if (data.toString("latin1", pe, pe + 4) !== "PE\0\0") throw new Error("Not a PE file");
  const optional = pe + 24; const magic = data.readUInt16LE(optional);
  const directories = optional + (magic === 0x20b ? 112 : 96);
  const security = directories + 4 * 8;
  const offset = data.readUInt32LE(security); const size = data.readUInt32LE(security + 4);
  if (!size) return data;
  if (offset + size < data.length - 8) throw new Error("Certificate table is not at the end of the file");
  const stripped = Buffer.from(data.subarray(0, offset));
  stripped.writeUInt32LE(0, security); stripped.writeUInt32LE(0, security + 4);
  return stripped;
}

export async function packageCompanion(target: Target, version: string, out: string) {
  if (!/^\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$/.test(version)) throw new Error("Version must be semver, e.g. 1.0.0");
  const work = join(root, "output", "sea", target); const cache = join(root, "output", "runtime");
  rmSync(work, { recursive: true, force: true }); mkdirSync(work, { recursive: true }); mkdirSync(out, { recursive: true });
  const bundle = join(work, "ai-usage.cjs");
  const { metafile } = await build({
    entryPoints: [join(root, "src", "cli.ts")], bundle: true, platform: "node", format: "cjs", target: "node24", absWorkingDir: root,
    outfile: bundle, define: { __AI_USAGE_COMPANION_VERSION__: JSON.stringify(version) }, logLevel: "warning", metafile: true,
  });
  // Shipped inside the binary (`meterkat licenses`) and next to it in the Linux archive.
  const notices = join(work, NOTICES_FILE);
  writeFileSync(notices, thirdPartyNotices(Object.keys(metafile.inputs)));
  // The companion's own licence (MIT), printed first by `meterkat licenses`.
  const license = join(root, LICENSE_FILE);
  // The blob format belongs to the runtime version, so the pinned runtime for the host generates it.
  const blob = join(work, "sea.blob"); const config = join(work, "sea-config.json");
  writeFileSync(config, JSON.stringify({ main: bundle, output: blob, disableExperimentalSEAWarning: true, useSnapshot: false, useCodeCache: false, assets: { [NOTICES_FILE]: notices, [LICENSE_FILE]: license } }));
  run(await nodeBinary(hostTarget(), cache), ["--experimental-sea-config", config]);
  const output = join(out, assetName(target, version)); const temporary = `${output}.tmp`;
  let executable: Buffer = readFileSync(await nodeBinary(target, cache));
  if (target.startsWith("windows")) executable = stripPeSignature(executable);
  writeFileSync(temporary, executable, { mode: 0o755 });
  await inject(temporary, "NODE_SEA_BLOB", readFileSync(blob), { sentinelFuse: SEA_FUSE });
  chmodSync(temporary, 0o755); renameSync(temporary, output);
  // Linux downloads lose the executable bit; the archive keeps it for manual installs.
  if (target.startsWith("linux")) {
    const staging = join(work, "archive"); mkdirSync(staging);
    copyFileSync(output, join(staging, "meterkat")); chmodSync(join(staging, "meterkat"), 0o755);
    copyFileSync(notices, join(staging, NOTICES_FILE)); copyFileSync(license, join(staging, LICENSE_FILE));
    run("tar", ["-czf", `${output}.tar.gz`, "--owner=0", "--group=0", "-C", staging, "meterkat", LICENSE_FILE, NOTICES_FILE]);
  }
  return output;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const { values } = parseArgs({ options: { target: { type: "string" }, version: { type: "string", default: "0.0.0-dev" }, out: { type: "string" } } });
  const target = (values.target ?? hostTarget()) as Target;
  if (!TARGETS.includes(target)) throw new Error(`Target must be one of ${TARGETS.join(", ")}`);
  const file = await packageCompanion(target, values.version!, resolve(values.out ?? join(root, "output", "dist")));
  console.log(`Built ${file} (Node ${runtime.version}, companion ${values.version})`);
}
